WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_cr_oppo'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '反向环形', 'kp-trv-cr-oppo', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "反向环形行程"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "背对背起跑的相遇，就是一次“把一圈拼满”的合作。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“400米跑道，两人同时背向起跑，甲速度6，乙速度4，问多久两人第一次相遇？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推论"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "反向环形，本质就是直线上的单次相遇。只不过把线段首尾相接弯成了圆。"}]}, {"type": "katexBlock", "attrs": {"content": "S_{一圈} = (V_{甲} + V_{乙}) \\times T_{相遇}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "同向反向记混淆：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "同向是追击（用减法），反向是相遇（用加法）。每次做环形题，必须用笔把“同向”或“背向”两个字圈起来！这是生与死的界限。"}]}]}]}$$ AS jsonb), NULL, '反向环形的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "反向环形"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_cr_oppo", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
